<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }

function kimpu_register_typography_controls( $customizer ) {
	$section = 'kimpu_design_typography'; $customizer->add_section( $section, array( 'title' => __( 'Typography', 'kimpu-multipurpose' ), 'panel' => 'kimpu_global_design', 'priority' => 30 ) );
	$fonts = array( 'system' => __( 'System Sans', 'kimpu-multipurpose' ), 'georgia' => __( 'Georgia Serif', 'kimpu-multipurpose' ), 'verdana' => __( 'Verdana', 'kimpu-multipurpose' ), 'tahoma' => __( 'Tahoma', 'kimpu-multipurpose' ), 'monospace' => __( 'Monospace', 'kimpu-multipurpose' ) );
	foreach ( array( 'kimpu_design_body_font' => __( 'Body Font Family', 'kimpu-multipurpose' ), 'kimpu_design_heading_font' => __( 'Heading Font Family', 'kimpu-multipurpose' ) ) as $id => $label ) { $customizer->add_setting( $id, array( 'default' => 'system', 'sanitize_callback' => function( $value ) use ( $fonts ) { return array_key_exists( $value, $fonts ) ? $value : 'system'; }, 'transport' => 'refresh' ) ); $customizer->add_control( $id, array( 'label' => $label, 'section' => $section, 'type' => 'select', 'choices' => $fonts ) ); }
	$fields = array( 'body_size' => array( 16, 13, 22, __( 'Base Font Size (px)', 'kimpu-multipurpose' ) ), 'body_weight' => array( 400, 300, 800, __( 'Body Font Weight', 'kimpu-multipurpose' ) ), 'body_line_height' => array( 1.65, 1.2, 2.2, __( 'Body Line Height', 'kimpu-multipurpose' ) ), 'body_letter_spacing' => array( 0, -0.1, 0.2, __( 'Body Letter Spacing (em)', 'kimpu-multipurpose' ) ), 'heading_weight' => array( 700, 400, 900, __( 'Heading Weight', 'kimpu-multipurpose' ) ), 'heading_line_height' => array( 1.18, 1, 1.6, __( 'Heading Line Height', 'kimpu-multipurpose' ) ), 'heading_letter_spacing' => array( -0.03, -0.12, 0.1, __( 'Heading Letter Spacing (em)', 'kimpu-multipurpose' ) ), 'nav_size' => array( 15, 11, 24, __( 'Navigation Font Size (px)', 'kimpu-multipurpose' ) ), 'nav_weight' => array( 600, 300, 800, __( 'Navigation Font Weight', 'kimpu-multipurpose' ) ), 'nav_letter_spacing' => array( 0, -0.1, 0.2, __( 'Navigation Letter Spacing (em)', 'kimpu-multipurpose' ) ), 'button_font_size' => array( 15, 11, 24, __( 'Button Font Size (px)', 'kimpu-multipurpose' ) ), 'button_weight' => array( 700, 400, 900, __( 'Button Font Weight', 'kimpu-multipurpose' ) ) );
	foreach ( $fields as $key => $data ) { $id = 'kimpu_design_' . $key; $customizer->add_setting( $id, array( 'default' => $data[0], 'sanitize_callback' => function( $value ) use ( $data ) { return kimpu_sanitize_design_number( $value, $data[1], $data[2] ); }, 'transport' => 'postMessage' ) ); $customizer->add_control( $id, array( 'label' => $data[3], 'section' => $section, 'type' => 'number', 'input_attrs' => array( 'min' => $data[1], 'max' => $data[2], 'step' => '0.01' ) ) ); }
	$heading_sizes = array( 'h1' => array( 56, 32, 96 ), 'h2' => array( 44, 26, 72 ), 'h3' => array( 32, 22, 56 ), 'h4' => array( 25, 18, 42 ), 'h5' => array( 20, 16, 32 ), 'h6' => array( 17, 14, 26 ) );
	foreach ( $heading_sizes as $key => $data ) { $id = 'kimpu_design_' . $key; $customizer->add_setting( $id, array( 'default' => $data[0], 'sanitize_callback' => function( $value ) use ( $data ) { return kimpu_sanitize_design_number( $value, $data[1], $data[2] ); }, 'transport' => 'postMessage' ) ); $customizer->add_control( $id, array( 'label' => strtoupper( $key ) . __( ' Size (px)', 'kimpu-multipurpose' ), 'section' => $section, 'type' => 'number', 'input_attrs' => array( 'min' => $data[1], 'max' => $data[2] ) ) ); }
}
